// Package windows holds the concrete device type implementation for
// windows gear ("windows_server"). Generated by pleiades forge new-device
// (internal/inventory/devicescaffold); mirrors the hand-written
// internal/inventory/devices/cisco and devices/linux packages.
//
// This package's init registers NewServer into the shared
// record.Types registry under "windows_server". internal/inventory/factory.go's
// NewItemFactory draws its batteries-included set from that registry
// rather than importing this package by name, so this package is NOT YET
// REACHABLE from the stock binary: internal/inventory/builtins.go's
// blank-import list is what actually triggers a device package's init(),
// and it still only names cisco and linux. Add a blank import of this
// package there (or to your own composition root) before this type is
// reachable through NewItemFactory(). This package itself never imports
// internal/inventory, only the leaf internal/inventory/record package plus
// pkg/inventory, pkg/capability, and pkg/policy, so internal/inventory can
// depend on it (via a future blank import) without a cycle back.
//
// Because this package lives under internal/, it is reachable only from
// code inside this module or a fork of it: Go's internal/ visibility rule
// blocks any other module from importing it at all. This generator is
// repo-contributor tooling, not end-user extensibility; a third-party
// device type arriving from outside this binary needs a separate,
// not-yet-built distribution mechanism, not this one.
//
// Scope: this file gives Server the structural skeleton every
// device type needs (a record.Base embed, a capability-baseline
// constructor, HasCapability, and the compile-time InventoryItem
// assertion below) but adds no capability-specific accessor methods,
// since pkg/capability.Descriptor's Assert is an opaque function with no
// reflectable method-set metadata this generator could read. Until a
// human adds real accessor methods matching each declared capability's
// interface, HasCapability correctly returns false for all of them: see
// the TODO on Server below.
package windows

import (
	"github.com/Subject-Void-LLC/the-pleiades/internal/inventory/record"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/capability"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/inventory"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/policy"
)

func init() {
	record.RegisterType("windows_server", NewServer)
}

// Server implements inventory.InventoryItem.
//
// It structurally implements WinRMCapable, via the WinRMHost and
// WinRMPort accessors below, which is what makes a Windows device
// reachable at all: the executor gates every dispatch on
// device.HasCapability(binding.Capability), and HasCapability is
// Declares(name) AND capability.Implements(w, name). Declaring
// WinRMCapable without implementing its two methods, which is what this
// type did until the WinRM transport arrived, means the gate refuses
// before any dial and the declaration is a claim the type cannot back.
//
// TODO(forge): Server declares three further capabilities it does not
// structurally implement, so HasCapability correctly returns false for
// each: WindowsCapable (needs WindowsEdition() string),
// WindowsServiceCapable, and WindowsFeatureCapable (needs
// DISMLogPath() string). Those gate the seven declared svc.windows.* and
// win.feature.* methods, which are not implemented either; wiring an
// accessor here before the method that needs it exists would replace a
// truthful "false" with an untested "true".
type Server struct {
	*record.Base
}

var _ inventory.InventoryItem = (*Server)(nil)

// NewServer builds a Server from rec. It matches the
// record.Constructor shape (func(record.Record) (inventory.InventoryItem,
// error)) record.RegisterType expects.
//
// The capability set is the vendor baseline given to
// "pleiades forge new-device" unioned with rec.Capabilities, per Phase
// 32's capability granularity decision: classification-derived data can
// only add to what this type already asserts about itself, never replace
// it.
func NewServer(rec record.Record) (inventory.InventoryItem, error) {
	caps := policy.UnionSlices(
		[]capability.Name{
			capability.Name("WindowsCapable"),
			capability.Name("WinRMCapable"),
			capability.Name("WindowsServiceCapable"),
			capability.Name("WindowsFeatureCapable"),
		},
		rec.Capabilities,
	)
	base := record.NewBase(rec, caps)
	return &Server{Base: base}, nil
}

// HasCapability checks the declared classification AND the structural
// registry assertion, so a true result is a guarantee, not a hope.
func (w *Server) HasCapability(name capability.Name) bool {
	return w.Declares(name) && capability.Implements(w, name)
}

// WinRMHost returns the configured management host for this server,
// reading the same "host" property linux.Server reads for SSH so one
// inventory file describes both kinds of device the same way.
func (w *Server) WinRMHost() string {
	host, _ := w.Properties().String("host")
	return host
}

// WinRMPort returns the configured WinRM port, defaulting to 5985.
//
// 5985 is the HTTP listener Enable-PSRemoting creates; 5986 is the HTTPS
// one. The default is the cleartext port because it is the one that
// exists on a stock host, and the WinRM transport compensates by
// requiring SPNEGO message encryption on it rather than by pretending
// the default is TLS.
func (w *Server) WinRMPort() int {
	if port, ok := w.Properties().Int("port"); ok && port != 0 {
		return port
	}
	return 5985
}
